-- Generated executable query. Run with SQLite against indus_weave.db.
WITH paid AS (SELECT emp_id,substr(month_start,1,7) month,SUM(amount) paid_amount FROM fact_payroll_line WHERE amount<>0 GROUP BY emp_id,substr(month_start,1,7)), att AS (SELECT a.emp_id,substr(d.full_date,1,7) month,SUM(a.status='Present') present_days FROM fact_attendance_daily a JOIN dim_date d ON d.date_key=a.date_key GROUP BY a.emp_id,substr(d.full_date,1,7)) SELECT p.emp_id,p.month,p.paid_amount,COALESCE(a.present_days,0) present_days FROM paid p LEFT JOIN att a ON a.emp_id=p.emp_id AND a.month=p.month WHERE COALESCE(a.present_days,0)=0 ORDER BY p.month,p.emp_id;
